                                                 "Figure 1 - A : Analyse par co-immunoprécipitation suivie d’un western blot dans les lignées cellulaires RPMI 8226 et SKMM1 exprimant une protéine RAS fusionnée à mNeonGreen. Les extraits protéiques totaux (« input ») et les protéines immunoprécipitées à l’aide d’un anticorps isotype contrôle ou dirigé contre mNeonGreen sont analysés par western blot avec des anticorps anti-SLC3A2 et anti-mNeonGreen. Le milieu est purifié. B : Analyse par immunofluorescence de la localisation de SLC3A2 dans les lignées RPMI 8226 et SKMM1. La fluorescence rouge correspond aux zones de proximité entre SLC3A2 et RAS. Les noyaux sont marqués au DAPI (bleu) et la membrane plasmique est marquée par la WGA (Wheat Germ Agglutinin) en vert. Les flèches indiquent une colocalisation. MERGE correspond à la superposition des images. C : Quantification de l’association entre SLC3A2 et RAS par Proximity Ligation Assay (PLA) dans les lignées RPMI 8226 et SKMM1. Les cellules sont transfectées avec un ARN interférent contrôle (shCTRL) ou dirigé contre NRAS (shNRAS), KRAS (shKRAS), SLC3A2 (shSLC3A2) ou SLC7A5 (shSLC7A5). SLC7A5 est un transporteur d’acides aminés. Le score PLA corres-pond au nombre de signaux détectés par cellule, reflétant l’interaction potentielle entre les deux protéines. Les différences statistiques sont indiquées par les astérisques *** (p \u003c 0,001)."
