                                                 "Figure 3 – A : Analyse par western blot de cellules surexprimant AKT1-FLAG seul ou en présence de quantités croissantes de MAPK6-HA ou de MAPK4-HA. L’expression de MAPK4 et MAPK6 est détectée avec un anticorps anti-HA (IB : HA). L’activation d’AKT est évaluée par la détection de sa phosphorylation sur les résidus Thr308 (p-AKT T308) et Ser473 (p-AKT S473). Le western blot anti-AKT-FLAG vérifie le niveau d’expression total d’AKT. B : Analyse par western blot de plusieurs lignées cellulaires tumorales (MCF7, PC3, H1299 et SUM159) après inhibition de l’expression de MAPK6. Dans les cellules MCF7, MAPK6 est invalidée par des shARN inductibles (iNT : contrôle non ciblant ; clones 3 et 5). Dans les cellules PC3, H1299 et SUM159, MAPK6 est invalidée par deux siARN indépendants (siA4 et siA6), comparés à un siRNA contrôle dirigé contre la luciférase (siLuc). Les western blots détectent MAPK6, les formes phosphorylées d’AKT sur la Thr308 et la Ser473, AKT total, la phosphorylation de GSK3β sur la sérine 9 (p-GSK3β S9), substrat d’AKT, ainsi que la β-actine utilisée comme contrôle de chargement. C : Analyse de la prolifération de cellules PC3 après extinction de MAPK6 par deux siARN indépendants (siA4 et siA6) ou traitement contrôle (siLuc). La prolifération cellulaire est mesurée à différents temps (1, 3 et 5 jours) par un test colorimétrique avec lecture de l’absorbance à 570 nm. Le préfixe “i” indique l’ajout de la condition étudiée. Les résultats sont présentés sous forme de moyenne ± erreur standard. Les différences statistiques sont indiquées par ns (non significatif) et *** (p \u003c 0,001)."
