                              "Type":  "QCM",
                              "Context":  "Association pour l’Accès Santé – Université Paris Cité Année Universitaire 2026-2027\nUE 2 : Biochimie\nDurée de l’épreuve : 1h30\nVérifiez que les informations saisies sur votre grille QCM sont correctes : nom, prénom et numéro étudiant.\nSeule l’utilisation du stylo à bille noir est autorisée pour cocher les grilles.\nVérifiez que les informations saisies sur votre grille QCM sont correctes : nom, prénom et numéro étudiant.\nSeule l’utilisation du stylo à bille noir est autorisée pour cocher les grilles.\nInformations réglementaires\nInformations sur l’épreuve\nLa glycolyse est une voie métabolique essentielle chez l’homme : elle transforme le glucose en pyruvate en produisant 2 ATP, le pyruvate sera potentiellement introduit dans le cycle de Krebs sous une autre forme. Dans cette voie, une enzyme catalyse une réaction d’importance capitale. Cette enzyme c’est l’aldolase EC 4.1.2.13 qui catalyse la séparation du fructose 1,6 bisphosphate en DHAP et G3P (Figure 1). Cette réaction est charnière car elle marque à la fois la fin de la phase de préparation et le début de la phase de restitution de la glycolyse, c’est la phase où l’ATP est produit.\nFigure 1 : réaction catalysée par l’aldolase",
