                                                 "La fructose 1,6-bisphosphate aldolase (FBA) de classe II est une enzyme essentielle à la gly-colyse/gluconéogenèse des bactéries, des champignons et des protozoaires. Il est important de noter que les humains ne possèdent pas ce type d’aldolase, mais plutôt une FBA de classe I qui est structurellement et mécanistiquement distincte des FBA de classe II. À ce titre, la FBA de classe II est considérée comme une cible pharmacologique potentielle pour le développement de nouveaux antibiotiques contre les bactéries pathogènes telles que Mycobacterium tuberculosis, l’agent responsable de la tuberculose (TB). À ce jour, plusieurs inhibiteurs compétitifs de type mimétique du substrat de la FBA de classe II ont été développés ; cependant, ils manquent soit de spécificité, soit de puissance, soit de propriétés qui limitent leur potentiel en tant que traitements thérapeutiques possibles. Récemment, grâce à un criblage assisté par des enzymes et basé sur la structure, nous avons identifié l’acide 8-hydroxyquinoléine carboxylique (HCA) qui a une CI50 de 10 ± 1 µM pour la FBA de classe II présente dans M.tuberculosis (MtFBA).",
                                                 "Figure 9 : Représentation de Lineweaver-Burk en présence de HCA de l’aldolase"
