                              "Context":  "Association pour l’Accès Santé – Université Paris Cité Année Universitaire 2026-2027\nUE 5 : Histologie - Embryologie\nDurée de l’épreuve : 1h\nVérifiez que les informations saisies sur votre grille QCM sont correctes : nom, prénom et numéro étudiant.\nSeule l’utilisation du stylo à bille noir est autorisée pour cocher les grilles.\nVérifiez que les informations saisies sur votre grille QCM sont correctes : nom, prénom et numéro étudiant.\nSeule l’utilisation du stylo à bille noir est autorisée pour cocher les grilles.\nInformations réglementaires\nInformations sur l’épreuve\nConcernant la préparation et la conservation des tissus, laquelle (lesquelles) des propositions suivantes est (sont) exacte(s) ?\nUn prélèvement histologique permet une analyse cytologique après congélation directe du tissu\nLa fixation d’un prélèvement histologique permet la conservation des structures et peut se faire quelques jours après le prélèvement\nPour la fixation, des liquides fixateurs sont utilisés tels que le formol ou le liquide de Bouin\nSelon la durée écoulée après le prélèvement histologique, la durée de fixation varie\nLa congélation directe du tissu dans l’azote liquide permet ensuite l’étude de l’ARN, l’ADN ou encore des protéines",
